//! Durable dirty-object journal for a derived encrypted search index.
//! This is not connected to production search or publication yet.
use super::*;

impl Vault {
 /// Install triggers in one transaction; existing content remains untouched.
 /// Object IDs are stable UUIDs in Atlas; primary ID changes are unsupported.
 /// All production search_chunks mutations occur in the same transaction as
 /// search_index or objects mutations; those triggers coalesce chunk updates.
 pub fn enable_search_journal(&self)->Result<(),String>{self.enable_search_journal_guarded(||Ok(()))}
 pub fn enable_search_journal_guarded(&self,verify:impl Fn()->Result<(),String>)->Result<(),String>{
  verify()?;
  let schema:String=self.db.query_row("SELECT sql FROM sqlite_master WHERE name='search_index'",[],|r|r.get(0)).map_err(|e|e.to_string())?;
  let plain=!schema.trim_start().to_ascii_uppercase().starts_with("CREATE VIRTUAL TABLE");
  let sql="BEGIN IMMEDIATE;
  CREATE TABLE IF NOT EXISTS atlas_fts_dirty(id TEXT PRIMARY KEY, generation INTEGER NOT NULL CHECK(generation>0));
  CREATE TABLE IF NOT EXISTS atlas_fts_sequence(id INTEGER PRIMARY KEY CHECK(id=1),seq INTEGER NOT NULL CHECK(typeof(seq)='integer' AND seq>=0));
  INSERT OR IGNORE INTO atlas_fts_sequence VALUES(1,0);
  CREATE TABLE IF NOT EXISTS atlas_fts_config(id INTEGER PRIMARY KEY CHECK(id=1));
  INSERT INTO atlas_fts_dirty(id,generation) SELECT id,ROW_NUMBER() OVER (ORDER BY id)+(SELECT seq FROM atlas_fts_sequence WHERE id=1) FROM objects WHERE NOT EXISTS(SELECT 1 FROM atlas_fts_config WHERE id=1) ON CONFLICT(id) DO NOTHING;
  INSERT OR IGNORE INTO atlas_fts_config VALUES(1);
  UPDATE atlas_fts_sequence SET seq=MAX(seq,COALESCE((SELECT MAX(generation) FROM atlas_fts_dirty),0)) WHERE id=1;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_index_insert AFTER INSERT ON search_index_content BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(new.c0,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_index_delete AFTER DELETE ON search_index_content BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(old.c0,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_index_update AFTER UPDATE ON search_index_content BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(old.c0,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(new.c0,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_object_delete AFTER DELETE ON objects BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(old.id,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_trash_insert AFTER INSERT ON trash BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(new.id,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_trash_delete AFTER DELETE ON trash BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(old.id,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_object_insert AFTER INSERT ON objects BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(new.id,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_object_update AFTER UPDATE ON objects BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(new.id,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_block_insert AFTER INSERT ON blocks BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(new.id,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_block_update AFTER UPDATE ON blocks BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(new.id,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_block_delete AFTER DELETE ON blocks BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(old.id,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  CREATE TRIGGER IF NOT EXISTS atlas_fts_trash_update AFTER UPDATE ON trash BEGIN UPDATE atlas_fts_sequence SET seq=seq+1 WHERE id=1; INSERT INTO atlas_fts_dirty VALUES(new.id,(SELECT seq FROM atlas_fts_sequence WHERE id=1)) ON CONFLICT(id) DO UPDATE SET generation=excluded.generation; END;
  ";
  let sql=if plain{sql.replace("ON search_index_content","ON search_index").replace("new.c0","new.id").replace("old.c0","old.id")}else{sql.to_owned()};
  let result=(||{self.db.execute_batch(&sql).map_err(|e|e.to_string())?;verify()?;self.db.execute_batch("COMMIT").map_err(|e|e.to_string())})();if result.is_err(){let _=self.db.execute_batch("ROLLBACK");}result
 }
 /// Monotonic across queue acknowledgements and application restarts.
 pub fn search_journal_sequence(&self)->Result<i64,String>{self.db.query_row("SELECT seq FROM atlas_fts_sequence WHERE id=1",[],|r|r.get(0)).map_err(|e|e.to_string())}
 /// Bounded snapshot; the consumer must acknowledge only after secondary commit.
 pub fn pending_search_updates(&self,limit:usize)->Result<Vec<(String,i64)>,String>{
  let mut s=self.db.prepare("SELECT id,generation FROM atlas_fts_dirty ORDER BY id LIMIT ?1").map_err(|e|e.to_string())?;
  let rows=s.query_map([limit.min(256) as i64],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|e|e.to_string())?;
  rows.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())
 }
 /// Full bounded journal snapshot for atomic checkpoint finalization.
 pub fn all_pending_search_updates(&self)->Result<Vec<(String,i64)>,String>{let mut stmt=self.db.prepare("SELECT id,generation FROM atlas_fts_dirty ORDER BY id LIMIT 100001").map_err(|e|e.to_string())?;let rows=stmt.query_map([],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|e|e.to_string())?;let items=rows.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?;if items.len()>100000{return Err("Очередь поиска слишком велика".into())}Ok(items)}
 /// Do not clear newer changes made while the derived index was being updated.
 pub fn acknowledge_search_update(&self,id:&str,generation:i64)->Result<bool,String>{
  let n=self.db.execute("DELETE FROM atlas_fts_dirty WHERE id=?1 AND generation=?2",params![id,generation]).map_err(|e|e.to_string())?;Ok(n==1)
 }
}

#[cfg(test)] mod tests {
 use super::*;
 #[test] fn updates_are_durable_and_old_ack_cannot_erase_new_edit(){
  let root=std::env::temp_dir().join(format!("atlas-fts-journal-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let path=root.join("vault");let mut v=Vault::create(&path,"secret").unwrap();v.enable_search_journal().unwrap();v.put_note("n","title","first").unwrap();let first=v.pending_search_updates(10).unwrap();assert_eq!(first.len(),1);v.put_note("n","title","second").unwrap();assert!(!v.acknowledge_search_update("n",first[0].1).unwrap());drop(v);let v=Vault::open(&path,"secret").unwrap();let pending=v.pending_search_updates(10).unwrap();assert_eq!(pending.len(),1);assert!(pending[0].1>first[0].1);assert!(v.acknowledge_search_update("n",pending[0].1).unwrap());assert!(v.pending_search_updates(10).unwrap().is_empty());drop(v);std::fs::remove_dir_all(root).unwrap();
 }
 #[test] fn guarded_install_rolls_back_if_medium_changes_before_commit(){let root=std::env::temp_dir().join(format!("atlas-journal-guard-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("vault"),"secret").unwrap();v.put_note("n","title","before").unwrap();let calls=std::cell::Cell::new(0);let result=v.enable_search_journal_guarded(||{let n=calls.get()+1;calls.set(n);if n==2{Err("medium disconnected".into())}else{Ok(())}});assert!(result.is_err());let count:i64=v.db.query_row("SELECT count(*) FROM sqlite_master WHERE name='atlas_fts_dirty'",[],|r|r.get(0)).unwrap();assert_eq!(count,0);assert_eq!(v.get_note("n").unwrap(),"before");v.enable_search_journal().unwrap();assert_eq!(v.pending_search_updates(10).unwrap().len(),1);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn old_ack_cannot_erase_later_generation_after_queue_was_empty(){let root=std::env::temp_dir().join(format!("atlas-fts-aba-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("vault"),"secret").unwrap();v.enable_search_journal().unwrap();v.put_note("n","title","first").unwrap();let old=v.pending_search_updates(10).unwrap()[0].1;assert!(v.acknowledge_search_update("n",old).unwrap());v.put_note("n","title","second").unwrap();let fresh=v.pending_search_updates(10).unwrap()[0].1;assert!(fresh>old);assert!(!v.acknowledge_search_update("n",old).unwrap());assert_eq!(v.pending_search_updates(10).unwrap()[0].1,fresh);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn legacy_backfill_is_atomic_and_not_repeated(){let root=std::env::temp_dir().join(format!("atlas-fts-backfill-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("vault"),"secret").unwrap();v.put_note("a","A","existing").unwrap();v.put_note("b","B","existing").unwrap();v.enable_search_journal().unwrap();let entries=v.pending_search_updates(10).unwrap();assert_eq!(entries.len(),2);for (id,generation) in entries{assert!(v.acknowledge_search_update(&id,generation).unwrap());}v.enable_search_journal().unwrap();assert!(v.pending_search_updates(10).unwrap().is_empty());v.put_note("a","A","edited").unwrap();assert_eq!(v.pending_search_updates(10).unwrap().len(),1);drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] #[ignore] fn benchmark_journal_overhead_for_large_note(){let root=std::env::temp_dir().join(format!("atlas-fts-journal-bench-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let text="слово test document ".repeat(100_000);for (i,enabled) in [false,true,true,false,false,true].into_iter().enumerate(){let mut v=Vault::create(&root.join(format!("trial-{i}")),"secret").unwrap();if enabled{v.enable_search_journal().unwrap()}let start=std::time::Instant::now();v.put_note("n","note",&text).unwrap();eprintln!("journal={enabled} bytes={} elapsed={:?}",text.len(),start.elapsed());if enabled{assert_eq!(v.pending_search_updates(10).unwrap().len(),1)}drop(v);}std::fs::remove_dir_all(root).unwrap();}
 #[test] fn note_file_image_rename_description_trash_restore_and_fts_mutations_are_journalled(){let root=std::env::temp_dir().join(format!("atlas-fts-crud-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("vault"),"secret").unwrap();v.enable_search_journal().unwrap();fn clear(v:&Vault,id:&str){let p=v.pending_search_updates(10).unwrap();let generation=p.iter().find(|(key,_)|key==id).expect("missing dirty object").1;assert!(v.acknowledge_search_update(id,generation).unwrap());}v.put_note("n","Note","text").unwrap();clear(&v,"n");v.put_note("n","Note","updated").unwrap();clear(&v,"n");v.put_file("image","image.png",&b"image data"[..],None).unwrap();clear(&v,"image");v.put_file("image","image.png",&b"replacement"[..],None).unwrap();clear(&v,"image");v.rename_file_guarded("image","renamed.png",||Ok(())).unwrap();clear(&v,"image");v.set_description("image","search description").unwrap();clear(&v,"image");v.trash_many(&["n".into()],1).unwrap();clear(&v,"n");v.restore_many(&["n".into()]).unwrap();clear(&v,"n");v.db.execute("UPDATE search_index SET title='direct' WHERE id='n'",[]).unwrap();clear(&v,"n");v.db.execute("DELETE FROM search_index WHERE id='n'",[]).unwrap();clear(&v,"n");drop(v);let reopened=Vault::open(&root.join("vault"),"secret").unwrap();assert!(reopened.pending_search_updates(10).unwrap().is_empty());drop(reopened);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn extraction_restore_draft_and_purge_paths_dirty_the_correct_object(){let root=std::env::temp_dir().join(format!("atlas-fts-paths-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("vault"),"secret").unwrap();v.enable_search_journal().unwrap();fn clear(v:&Vault,id:&str){let p=v.pending_search_updates(10).unwrap();let generation=p.iter().find(|(key,_)|key==id).expect("missing dirty object").1;assert!(v.acknowledge_search_update(id,generation).unwrap());}v.put_file("file","doc.txt",&b"some extracted words"[..],None).unwrap();clear(&v,"file");v.extract_file_text("file").unwrap();clear(&v,"file");v.put_note("n","Note","original").unwrap();clear(&v,"n");v.save_note_draft_guarded("n","Note","draft recovered",||Ok(())).unwrap();v.trash_many(&["n".into()],0).unwrap();clear(&v,"n");v.restore_many(&["n".into()]).unwrap();clear(&v,"n");assert_eq!(v.get_note("n").unwrap(),"draft recovered");v.trash_many(&["n".into()],0).unwrap();clear(&v,"n");v.purge_trash_before_guarded(1,||Ok(())).unwrap();clear(&v,"n");drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn journal_installs_on_plain_content_store(){let root=std::env::temp_dir().join(format!("atlas-fts-plain-journal-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut v=Vault::create(&root.join("vault"),"secret").unwrap();v.put_note("n","note","old").unwrap();v.db.execute_batch("ALTER TABLE search_index RENAME TO old_search_index; CREATE TABLE search_index(id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,description TEXT NOT NULL); INSERT INTO search_index SELECT * FROM old_search_index; DROP TABLE search_chunks;").unwrap();v.enable_search_journal().unwrap();let (id,generation)=v.pending_search_updates(1).unwrap().pop().unwrap();assert!(v.acknowledge_search_update(&id,generation).unwrap());v.db.execute("UPDATE search_index SET body='new' WHERE id='n'",[]).unwrap();assert_eq!(v.pending_search_updates(1).unwrap()[0].0,"n");drop(v);std::fs::remove_dir_all(root).unwrap();}
 #[test] fn rolled_back_writes_do_not_create_journal_entries(){
  let root=std::env::temp_dir().join(format!("atlas-fts-rollback-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let path=root.join("vault");let v=Vault::create(&path,"secret").unwrap();v.enable_search_journal().unwrap();v.db.execute_batch("BEGIN; INSERT INTO search_index VALUES('n','t','secret',''); ROLLBACK;").unwrap();assert!(v.pending_search_updates(10).unwrap().is_empty());drop(v);std::fs::remove_dir_all(root).unwrap();
 }
}
